<!doctype html><html lang="id"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Daftar ShopEase</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"></head><body class="bg-light"><div class="container py-5"><div class="card mx-auto p-4" style="max-width:440px"><a href="<?= site_url('/') ?>">← ShopEase</a><h2 class="mt-3">Buat akun</h2><?php if(session()->getFlashdata('errors')): ?><div class="alert alert-danger"><?php foreach(session()->getFlashdata('errors') as $e): ?><?= esc($e) ?><br><?php endforeach; ?></div><?php endif; ?><form method="post" action="<?= site_url('register') ?>"><?= csrf_field() ?><label class="form-label">Nama</label><input name="name" class="form-control mb-3" value="<?= old('name') ?>" required><label class="form-label">Email</label><input name="email" type="email" class="form-control mb-3" value="<?= old('email') ?>" required><label class="form-label">Password (minimal 8 karakter)</label><input name="password" type="password" class="form-control mb-3" required><button class="btn btn-success w-100">Daftar</button></form><p class="mt-3 mb-0">Sudah punya akun? <a href="<?= site_url('login') ?>">Masuk</a></p></div></div></body></html>
